-- Planned D1 schema. Apply locally first; do not run against production without review.
CREATE TABLE IF NOT EXISTS ai_sources (id TEXT PRIMARY KEY, url TEXT NOT NULL, type TEXT NOT NULL, language TEXT NOT NULL, region TEXT NOT NULL, interval_hours INTEGER NOT NULL, priority INTEGER NOT NULL, active INTEGER NOT NULL, last_checked_at TEXT, last_error TEXT);
CREATE TABLE IF NOT EXISTS ai_items (id TEXT PRIMARY KEY, source_id TEXT NOT NULL, external_id TEXT, canonical_url TEXT NOT NULL UNIQUE, kind TEXT NOT NULL, title TEXT NOT NULL, summary TEXT, published_at TEXT, fetched_at TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_candidates (id TEXT PRIMARY KEY, item_id TEXT, kind TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','pending_review','approved','published','rejected','failed')), title TEXT NOT NULL, description TEXT NOT NULL, body TEXT NOT NULL, category TEXT, region TEXT, tags_json TEXT NOT NULL DEFAULT '[]', sources_json TEXT NOT NULL, verification_json TEXT NOT NULL, event_json TEXT, ai_generated INTEGER NOT NULL DEFAULT 0, cms_path TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_candidate_history (id INTEGER PRIMARY KEY AUTOINCREMENT, candidate_id TEXT NOT NULL, previous_status TEXT, new_status TEXT NOT NULL, actor_id TEXT, at TEXT NOT NULL, note TEXT);
CREATE TABLE IF NOT EXISTS ai_runs (id TEXT PRIMARY KEY, started_at TEXT NOT NULL, finished_at TEXT, found INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL DEFAULT 0, duplicates INTEGER NOT NULL DEFAULT 0, rejected INTEGER NOT NULL DEFAULT 0, errors_json TEXT NOT NULL DEFAULT '[]', status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT, provider TEXT NOT NULL, model TEXT NOT NULL, input_tokens INTEGER NOT NULL, output_tokens INTEGER NOT NULL, estimated_cost_usd REAL NOT NULL, at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ai_config (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_at TEXT NOT NULL);
